using System;
using System.Collections.Generic;
using UnityEngine;

// Bounded planet-relative scenery. Rock sweeps are gameplay contacts, independent of Unity rigidbodies.
public sealed class SpaceEnvironment : MonoBehaviour {
 public sealed class Rock {public int id;public Vector3 local;public float radius,hp=45;public Transform view;public Vector3 spin;}
 public sealed class Orbital {public string name;public Transform root;public float radius,phase,rate,collision;public bool station,scanned;}
 public readonly List<Rock> Rocks=new List<Rock>();public readonly List<Orbital> Orbitals=new List<Orbital>();
 public PlanetExpedition.Planet Planet{get;private set;}public int Mined{get;private set;} public int Collisions{get;private set;}
 DefenseGame game;PlanetExpedition ground;SurfaceArt art;Material rockMaterial;Transform field,comet;LineRenderer tail;List<Mesh> meshes=new List<Mesh>();List<Rock> catalogue=new List<Rock>();Dictionary<string,HashSet<int>> mined=new Dictionary<string,HashSet<int>>();Mesh habitatMesh;HashSet<string> scanned=new HashSet<string>();float refresh,serviceCooldown;Vector3 selectionPoint;double time;
 public void Initialize(DefenseGame owner,PlanetExpedition expedition){game=owner;ground=expedition;art=new SurfaceArt();rockMaterial=new Material(Shader.Find("Orbit/Asteroid"));rockMaterial.SetTexture("_Rock",Resources.Load<Texture2D>("Surfaces/rock_diff"));rockMaterial.SetTexture("_RockNormal",Resources.Load<Texture2D>("Surfaces/rock_normal"));for(int i=0;i<8;i++)meshes.Add(RockMesh(i));}
 Mesh RockMesh(int seed){var g=new SurfaceArt.Geometry();g.Ellipsoid(Vector3.zero,Vector3.one,new Color(.3f,.3f,.3f),12,8);for(int i=0;i<g.vertices.Count;i++){Vector3 v=g.vertices[i];float h=Mathf.PerlinNoise(v.x*2.8f+seed*7,v.z*2.6f+v.y*1.7f+seed*3);g.vertices[i]=v*(.72f+h*.38f);}return g.Mesh("Shared cratered asteroid / "+seed);}
 public void ResetAll(){Clear();mined.Clear();scanned.Clear();Mined=Collisions=0;time=0;serviceCooldown=0;}
 void Clear(){if(field!=null)Destroy(field.gameObject);field=null;Planet=null;catalogue.Clear();Rocks.Clear();Orbitals.Clear();comet=null;tail=null;refresh=0;}
 static int Seed(string s){unchecked{int n=4307;foreach(char c in s)n=n*31+c;return n;}}
 void Build(PlanetExpedition.Planet planet){Clear();Planet=planet;field=new GameObject("ORBITAL ENVIRONMENT / "+planet.name).transform;field.position=planet.body.P;var rng=new System.Random(Seed(planet.key)^4307);if(!mined.ContainsKey(planet.key))mined.Add(planet.key,new HashSet<int>());
  // A broad polar rubble belt crosses the starting flight region and remains stable on revisits.
  for(int i=0;i<640;i++){float angle=i*2.39996323f,r=(float)planet.body.radius+1800+((float)rng.NextDouble()-.5f)*700;Vector3 local=new Vector3(Mathf.Sin(angle)*r,Mathf.Cos(angle)*r,((float)rng.NextDouble()-.5f)*900);float radius=7+(float)rng.NextDouble()*24;if(planet.key=="HOME"&&Vector3.Distance(local,new Vector3(-35,7800,-14))<130)continue;catalogue.Add(new Rock{id=i,local=local,radius=radius,spin=new Vector3((float)rng.NextDouble()*7+1,(float)rng.NextDouble()*5,(float)rng.NextDouble()*8)});}
  for(int i=0;i<3;i++){var sat=Satellite("KEPLER "+(i+1),i);Orbitals.Add(new Orbital{name="KEPLER "+(i+1)+" / SATELLITE",root=sat,radius=(float)planet.body.radius+1780+i*350,phase=.035f+i*.65f,rate=Mathf.Sqrt((float)planet.body.mu/Mathf.Pow((float)planet.body.radius+1780+i*350,3)),collision=7});}
  var station=Station();Orbitals.Add(new Orbital{name="WAYFARER RESEARCH / 0/F4 SERVICE",root=station,radius=(float)planet.body.radius+2050,phase=.17f,rate=.0035f,collision=39,station=true});
  var wreck=Wreck();Orbitals.Add(new Orbital{name="DERELICT FREIGHTER / 0/F4 SCAN",root=wreck,radius=(float)planet.body.radius+1750,phase=-.12f,rate=.0015f,collision=20});
  comet=art.MeshObject("Passing icy debris / artistic comet tail",field,meshes[3],art.ceramic).transform;comet.localScale=Vector3.one*12;tail=new GameObject("Ion tail / illustrative solar wind direction").AddComponent<LineRenderer>();tail.transform.SetParent(field,false);tail.sharedMaterial=art.BeamMaterial(new Color(.12f,.55f,1,.6f));tail.startWidth=13;tail.endWidth=0;tail.positionCount=6;tail.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;UpdateOrbits();
 }
 Transform Root(string name){return JointMotion.Joint(name,field,Vector3.zero);}
 Transform Piece(Transform parent,string name,PrimitiveType type,Vector3 p,Vector3 size,Material material){return art.Piece(name,parent,type,p,size,material);}
 Transform Satellite(string name,int index){var root=Root(name);Piece(root,"Thermal blanket service bus",PrimitiveType.Cube,Vector3.zero,new Vector3(3.5f,3.5f,4),art.amber);Piece(root,"Instrument aperture",PrimitiveType.Cylinder,new Vector3(0,0,3),new Vector3(2,1.3f,2),art.dark).localRotation=Quaternion.Euler(90,0,0);
  for(int side=-1;side<=1;side+=2){Piece(root,"Array hinge",PrimitiveType.Cylinder,new Vector3(side*4,0,0),new Vector3(.25f,3,.25f),art.metal).localRotation=Quaternion.Euler(0,0,90);var wing=JointMotion.Joint("Sun-tracking solar wing",root,new Vector3(side*9,0,0));Piece(wing,"Photovoltaic array",PrimitiveType.Cube,Vector3.zero,new Vector3(12,.12f,4.5f),art.dark);for(int cell=0;cell<10;cell++)Piece(wing,"Solar cell grid",PrimitiveType.Cube,new Vector3(-5.4f+cell*1.2f,.085f,0),new Vector3(.045f,.035f,4.4f),art.ceramic);Piece(wing,"Solar bus",PrimitiveType.Cube,Vector3.up*.1f,new Vector3(11.8f,.025f,.045f),art.cyan);}
  Piece(root,"High gain antenna",PrimitiveType.Sphere,Vector3.up*3,new Vector3(3.5f,.35f,3.5f),art.ceramic);Piece(root,"Antenna feed",PrimitiveType.Cylinder,Vector3.up*4,new Vector3(.22f,.7f,.22f),art.metal);return root;}
 Mesh Torus(float major,float minor){if(habitatMesh!=null)return habitatMesh;var g=new SurfaceArt.Geometry();int a=64,b=10;for(int i=0;i<=a;i++)for(int j=0;j<=b;j++){float u=i*Mathf.PI*2/a,v=j*Mathf.PI*2/b;g.vertices.Add(new Vector3(Mathf.Cos(u)*(major+minor*Mathf.Cos(v)),Mathf.Sin(v)*minor,Mathf.Sin(u)*(major+minor*Mathf.Cos(v))));g.colors.Add(Color.white);if(i<a&&j<b){int k=i*(b+1)+j;g.triangles.AddRange(new[]{k,k+1,k+b+1,k+1,k+b+2,k+b+1});}}var m=g.Mesh("Rotating orbital habitat torus");meshes.Add(m);habitatMesh=m;return m;}
 Transform Station(){var root=Root("WAYFARER ORBITAL RESEARCH");Piece(root,"Pressurized central spine",PrimitiveType.Cylinder,Vector3.zero,new Vector3(11,26,11),art.ceramic);var rotor=JointMotion.Joint("Rotating habitat",root,Vector3.zero);art.MeshObject("Habitat ring",rotor,Torus(42,4),art.metal);for(int i=0;i<8;i++){float a=i*Mathf.PI/4;Vector3 v=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var spoke=Piece(rotor,"Habitat spoke",PrimitiveType.Cube,v*22,new Vector3(3,3,37),art.ceramic);spoke.rotation=Quaternion.LookRotation(v);Piece(rotor,"Habitat window bank",PrimitiveType.Cube,v*43+Vector3.up*2,new Vector3(3,1,3),art.cyan);}
  for(int side=-1;side<=1;side+=2){Piece(root,"Docking arm",PrimitiveType.Cube,new Vector3(0,side*19,0),new Vector3(7,2,70),art.metal);for(int z=-1;z<=1;z+=2){var solar=Piece(root,"Research solar field",PrimitiveType.Cube,new Vector3(28,side*19,z*26),new Vector3(40,.35f,18),art.dark);for(int line=0;line<15;line++)Piece(solar,"PV cell seam",PrimitiveType.Cube,new Vector3(-.47f+line*.067f,.6f,0),new Vector3(.008f,.035f,.98f),art.ceramic);}Piece(root,"Docking beacon",PrimitiveType.Sphere,new Vector3(0,side*28,0),Vector3.one*3,art.cyan);}
  return root;}
 Transform Wreck(){var root=Root("Abandoned cargo tug");Piece(root,"Damaged freighter hull",PrimitiveType.Capsule,Vector3.zero,new Vector3(7,18,8),art.metal).localRotation=Quaternion.Euler(90,0,0);for(int i=0;i<5;i++)Piece(root,"Cargo pod",PrimitiveType.Cube,new Vector3((i%2==0?1:-1)*6,0,-12+i*5),new Vector3(5,6,5),i%2==0?art.ceramic:art.amber);for(int side=-1;side<=1;side+=2)Piece(root,"Engine bell",PrimitiveType.Cylinder,new Vector3(side*4,0,-20),new Vector3(4,3,4),art.dark).localRotation=Quaternion.Euler(90,0,0);root.localRotation=Quaternion.Euler(13,25,18);return root;}
 void UpdateOrbits(){if(Planet==null)return;field.position=Planet.body.P;foreach(var o in Orbitals){float angle=o.phase+(float)time*o.rate;o.root.localPosition=new Vector3(Mathf.Sin(angle)*o.radius,Mathf.Cos(angle)*o.radius,o.station?180:100);o.root.localRotation=Quaternion.Euler(0,0,-angle*Mathf.Rad2Deg);var rotor=o.root.Find("Rotating habitat");if(rotor!=null)rotor.localRotation=Quaternion.Euler(0,(float)time*8,0);foreach(Transform t in o.root)if(t.name=="Sun-tracking solar wing")t.localRotation=Quaternion.Euler(18+Mathf.Sin((float)time*.1f)*8,0,0);}
  float a=.7f+(float)time*.0018f,r=(float)Planet.body.radius+2500;comet.localPosition=new Vector3(Mathf.Sin(a)*r,Mathf.Cos(a)*r,-1100);Vector3 end=comet.position+new Vector3(-350,180,-100);for(int i=0;i<6;i++)tail.SetPosition(i,Vector3.Lerp(comet.position,end,i/5f));}
 public void Tick(float dt,bool active,Vector3 focus){if(ground==null)return;var p=ground.Nearest(focus);if(p==null)return;if(Planet!=p)Build(p);if(active){time+=dt;serviceCooldown=Mathf.Max(0,serviceCooldown-dt);}UpdateOrbits();refresh-=dt;if(refresh<=0||(focus-selectionPoint).sqrMagnitude>1000000){refresh=.6f;selectionPoint=focus;SelectRocks(focus);}foreach(var r in Rocks)if(r.view!=null&&active)r.view.Rotate(r.spin*dt,Space.Self);}
 void SelectRocks(Vector3 focus){var visible=new List<Rock>();foreach(var r in catalogue)if(!mined[Planet.key].Contains(r.id)&&(r.local+Planet.body.P-focus).sqrMagnitude<6500*6500)visible.Add(r);visible.Sort((a,b)=>(a.local+Planet.body.P-focus).sqrMagnitude.CompareTo((b.local+Planet.body.P-focus).sqrMagnitude));if(visible.Count>160)visible.RemoveRange(160,visible.Count-160);foreach(var r in Rocks)if(!visible.Contains(r)&&r.view!=null){Destroy(r.view.gameObject);r.view=null;}Rocks.Clear();Rocks.AddRange(visible);foreach(var r in Rocks)if(r.view==null){r.view=art.MeshObject("Mineable asteroid / "+r.id,field,meshes[r.id%8],rockMaterial).transform;r.view.localPosition=r.local;r.view.localScale=Vector3.one*r.radius;r.view.localRotation=Quaternion.Euler(r.id*17,r.id*41,r.id*7);}}
 public Vector3 World(Rock r){return Planet.body.P+r.local;}
 public static bool Sweep(Vector3 start,Vector3 end,Vector3 center,float radius,out float t){Vector3 d=end-start,q=start-center;float a=d.sqrMagnitude,c=q.sqrMagnitude-radius*radius;t=0;if(c<0)return true;if(a<.0000001f)return false;float b=Vector3.Dot(q,d),disc=b*b-a*c;if(disc<0)return false;t=(-b-Mathf.Sqrt(disc))/a;return t>=0&&t<=1;}
 public float ResolveShip(ref OrbitDemo.State state,Vector3 before){if(Planet==null)return 0;Vector3 end=DefenseGame.Pos(state),point=Vector3.zero;float hit=2,radius=0;foreach(var r in Rocks)if(Sweep(before,end,World(r),r.radius*.92f+1,out float t)&&t<hit){hit=t;point=World(r);radius=r.radius*.92f+1;}foreach(var o in Orbitals)if(Sweep(before,end,o.root.position,o.collision+1,out float t)&&t<hit){hit=t;point=o.root.position;radius=o.collision+1;}if(hit>1)return 0;Vector3 normal=(Vector3.Lerp(before,end,hit)-point).normalized;if(normal.sqrMagnitude<.1f)normal=(before-point).normalized;Vector3 v=DefenseGame.Vel(state);float inward=Vector3.Dot(v,normal);Vector3 p=point+normal*(radius+.1f);v-=normal*Mathf.Min(0,inward)*1.15f;state.x=p.x;state.y=p.y;state.z=p.z;state.vx=v.x;state.vy=v.y;state.vz=v.z;Collisions++;return Mathf.Max(0,-inward);}
 public bool Hit(Vector3 a,Vector3 b,bool playerShot){if(Planet==null)return false;Rock closest=null;float near=2;foreach(var r in Rocks)if(Sweep(a,b,World(r),r.radius*.92f,out float t)&&t<near){near=t;closest=r;}if(closest!=null){if(playerShot){closest.hp-=24;CinematicPresentation.Impact(Vector3.Lerp(a,b,near),new Color(1,.6f,.25f));if(closest.hp<=0){mined[Planet.key].Add(closest.id);if(closest.view!=null)Destroy(closest.view.gameObject);Rocks.Remove(closest);Mined++;game.GroundReward(75,2);game.GroundNotice("ASTEROID MINED / +75 score / +2 parts");}}return true;}foreach(var o in Orbitals)if(Sweep(a,b,o.root.position,o.collision,out float t))return true;return false;}
 public bool Service(Vector3 player,float speed){if(Planet==null)return false;Orbital nearest=null;float range=160;foreach(var o in Orbitals){float d=Vector3.Distance(player,o.root.position);if(d<range){nearest=o;range=d;}}if(nearest==null){game.GroundNotice("0 / F4 / approach a station or satellite within 160m to service or scan");return false;}if(speed>15){game.GroundNotice("Reduce speed below 15m/s for orbital service");return false;}if(nearest.station){if(serviceCooldown>0){game.GroundNotice("Station repair recharge / "+serviceCooldown.ToString("F0")+"s");return false;}game.GroundHeal(100);serviceCooldown=60;game.GroundNotice("RESEARCH STATION / hull repaired");return true;}if(scanned.Contains(Planet.key+nearest.name)){game.GroundNotice("Orbital telemetry already downloaded");return false;}nearest.scanned=true;scanned.Add(Planet.key+nearest.name);game.GroundReward(125,2);game.GroundNotice("ORBITAL TELEMETRY / +125 score / +2 parts");return true;}
 public Vector3 Avoid(Vector3 p,Vector3 v){if(Planet==null||v.magnitude<20)return Vector3.zero;Vector3 ray=v.normalized;float range=Mathf.Clamp(v.magnitude*4,200,10000),best=range;Vector3 force=Vector3.zero;foreach(var r in Rocks){Vector3 delta=World(r)-p;float d=Vector3.Dot(delta,ray);Vector3 side=Vector3.ProjectOnPlane(p-World(r),ray);if(d<=0||d>best||side.magnitude>r.radius+110)continue;best=d;if(side.sqrMagnitude<.01f)side=Vector3.Cross(ray,Vector3.up);force=side.normalized*Mathf.Clamp((r.radius+140-side.magnitude)*3,0,450)-ray*Mathf.Clamp(v.magnitude*v.magnitude/Mathf.Max(40,d)*.6f,0,650);}return force;}
 public void Shift(Vector3 shift){if(field!=null)field.position-=shift;selectionPoint-=shift;if(tail!=null)for(int i=0;i<tail.positionCount;i++)tail.SetPosition(i,tail.GetPosition(i)-shift);}
 public void Draw(Camera cam,Vector3 focus,bool onFoot){if(Planet==null||onFoot)return;foreach(var o in Orbitals){Vector3 s=cam.WorldToScreenPoint(o.root.position);if(s.z<=0||s.x<30||s.x>Screen.width-30||s.y<130||s.y>Screen.height-130)continue;float x=s.x/Screen.width*1600,y=1000-s.y/Screen.height*1000;GUI.color=new Color(.35f,.85f,1,.85f);GUI.Label(new Rect(x-140,y,520,38),o.name+" / "+Vector3.Distance(focus,o.root.position).ToString("F0")+"m");GUI.color=Color.white;}}
 void OnDestroy(){Clear();foreach(var m in meshes)if(m!=null)Destroy(m);if(art!=null)art.Dispose();if(rockMaterial!=null)Destroy(rockMaterial);}
}
